 README_underdog.md
JAIDEUnderdog V1 – FromScratch Polyglot LLM Stack
 IR és fordítás: AnyDSL/Impala → Thorin IR → több backend (CPU/GPU/FPGA), részleges kiértékeléssel [1][3].  
 GPU kernelek: Dex DSL kernelek (SSM update, lowrank, kvantálás operátorok) [7].  
 Orkesztráció: Pony actors (router, scheduler, KVclient), nanomsg/NNG hálózat [4][5].  
 Szabálymotor: λPrologszerű modul + statikus szabálykapu (Deduktistílusú ellenőrző illesztési pont) [8].  
 Cél: hosszú kontextusú SSM + HashedMoE + TTkvantálás, saját IRpassokkal; nincs finomhangolás, csak „from scratch” komponensek [1][3].  

 scripts/build_underdogV1.sh
!/usr/bin/env bash
set euo pipefail

echo "[1/6] Fetch AnyDSL/Thorin core"
test d toolchain/anydsl || mkdir p toolchain/anydsl
 Feltételezett AnyDSL lokális vendoring; saját Impala forrásaink a repoban
echo "[2/6] Build Impala → Thorin IR"
python3 scripts/impala_build.py toolchain/anydsl/impala src=toolchain/anydsl/impala/core.imp out=ir/thorin/core.thorin

echo "[3/6] Build Dex GPU kernels"
dex build kernels/dex/ssm_update.dx o build/ssm_update.kso
dex build kernels/dex/tt_quant.dx o build/tt_quant.kso

echo "[4/6] Build Pony runtime"
ponyc runtime/pony o build/pony Drelease

echo "[5/6] Build NNG glue"
cc O3 I/usr/include L/usr/lib lnng o build/nng_bus net/nng/bus.c

echo "[6/6] Link minimal driver"
cc O3 o build/driver src/driver.c

echo "✅ Underdog V1 build complete" [1][7][4].

 toolchain/anydsl/impala/core.imp (SSM, MoE, TTquant IRút)
fn dot(a: &f32[], b: &f32[]) > f32 { var s: f32 = 0.0; for i in 0..len(a) { s = s + a[i]b[i]; } s }
fn relu(x: f32) > f32 { if x > 0.0 { x } else { 0.0 } }
fn ssm_step(x: &f32[], state: &f32[], A:&f32[][], B:&f32[][]) > f32[] {
  var y: f32[] = alloc(len(state));
  for i in 0..len(state) {
    var acc = dot(A[i], state) + dot(B[i], x);
    y[i] = relu(acc);
  }
  y
}
fn low_rank_update(state:&f32[][], U:&f32[][], V:&f32[][]) > f32[][] {
  var out: f32[][] = alloc2(len(state), len(state));
  for i in 0..len(state) {
    for j in 0..len(state) {
      var s = state[i][j];
      var r = 0..len(U);
      var tmp: f32 = 0.0;
      for k in r { tmp = tmp + U[i][k]V[k][j]; }
      out[i][j] = s + tmp;
    }
  }
  out
}
fn tt_quantize(w:&f32[][], qbits: i32) > f32[][] {
  var out: f32[][] = alloc2(len(w), len(w));
  var levels = 1 << qbits;
  for i in 0..len(w) {
    for j in 0..len(w) {
      var v = w[i][j];
      var cl = clamp(v, 1.0, 1.0);
      var idx = round(((cl + 1.0)0.5)  (levels1) as f32);
      var deq = (idx/(levels1) as f32)2.0  1.0;
      out[i][j] = deq;
    }
  }
  out
}
export fn forward(tokens:&i32[], params: &f32[][], A:&f32[][], B:&f32[][]) > f32[] {
  var state: f32[] = alloc(len(A));
  for t in 0..len(tokens) {
    var x: f32[] = embed_token(tokens[t]); // saját embed
    state = ssm_step(x, state, A, B);
  }
  state
} [1][2][3].

Megjegyzés: a fenti Impala forrásokat Thorin IRre fordítjuk; a Thorin CPS/seaofnodes IR adja a passok táptalaját (inlining, részleges kiértékelés, adatelrendezés), több backend célzással [1][2][3].

